#!/usr/bin/env python3
"""Generate a large single-module Ballerina program of ordinary functions
(arithmetic, comparisons, calls, records, unions, returns) - no lambdas.
Usage: gen_stage6.py N OUT.bal"""
import sys
n = int(sys.argv[1]); out = sys.argv[2]
o = ["import ballerina/io;", "",
     "type Point record {| int x; int y; |};", "",
     "function add(int a, int b) returns int => a + b;", "",
     "function scale(Point p, int k) returns Point => {x: p.x * k, y: p.y * k};", ""]
for i in range(n):
    o.append(f"""function f{i}(int a, int b, string s, Point p, int? opt) returns int|error {{
    int x = a * {i % 7 + 1} + b - {i};
    int y = add(x, b) % 1000;
    boolean ok = x > y && s.length() > 0 || a == b;
    float f = <float>x / 3.0 + 1.5;
    decimal d = <decimal>y * 2.5d;
    string t = s + "-" + x.toString();
    int|string u = ok ? x : t;
    if u is int {{
        x += u;
    }} else {{
        x += u.length();
    }}
    Point q = scale(p, {i % 5 + 1});
    int z = q.x + q.y + (opt ?: 0);
    if f > 10.0 && d < 1000d {{
        z -= 1;
    }} else if z == x {{
        z += <int>f;
    }}
    while z > 100 {{
        z = z / 2;
    }}
    return x + y + z + t.length();
}}
""")
o.append("public function main() returns error? {")
o.append("    int total = 0;")
o.append("    Point p = {x: 1, y: 2};")
for i in range(0, n, max(1, n // 200)):
    o.append(f"    total += check f{i}(total % 97, {i}, \"k\", p, ());")
o.append("    io:println(total);")
o.append("}")
open(out, "w").write("\n".join(o) + "\n")

