+// validateConcurrently validates each of the independent declarations in nodes
+// under its own span, spread over a pool of goroutines that each use their
+// own type context. Once all have been validated, it reports their diagnostics
+// in declaration order and re-raises, on the calling goroutine, the panic of
+// the first declaration that panicked, so the outcome is that of validating
+// them serially.
+func validateConcurrently[T interface{ GetName() ast.IdentifierNode }](
+	cx scope.Context, nodes []T, operation string, validate func(scope.Context, T), parent context.TraceSpan,
+) {
+	type outcome struct {
+		flush    func()
+		panicked any
+	}
+	outcomes := make([]outcome, len(nodes))
+	var next atomic.Int64
+	var wg sync.WaitGroup
+	for range min(runtime.GOMAXPROCS(0), len(nodes)) {
+		wg.Go(func() {
+			tyCtx := semtypes.ContextFrom(cx.CompilerCtx().GetTypeEnv())
+			for i := int(next.Add(1) - 1); i < len(nodes); i = int(next.Add(1) - 1) {
+				fork, flush := scope.Fork(cx, tyCtx)
+				outcomes[i].flush = flush
+				func() {
+					defer func() { outcomes[i].panicked = recover() }()
+					span := parent.StartChild(operation, nodes[i].GetName().GetValue())
+					validate(fork, nodes[i])
+					span.End()
+				}()
+			}
+		})
+	}
+	wg.Wait()
+	for _, o := range outcomes {
+		o.flush()
+		if o.panicked != nil {
+			panic(o.panicked)
+		}
 	}
 }

